#pragma once

// The advance widths of PDF's standard 14 fonts, which a reader knows
// without the fonts (ISO 32000-2 §9.6.2.2): generated by
// tools/gen-std14-metrics.cpp into Std14Metrics.cpp.

#include <optional>
#include <span>
#include <string_view>

namespace sashfold::pdf {

struct NamedWidth {
    char const* name; // a glyph name
    short width; // per 1000 of the font size
};

// A text font's widths by glyph name (sorted by name), or a symbolic
// font's by code.
struct Std14Widths {
    std::span<NamedWidth const> by_name;
    short const* by_code = nullptr; // 256 entries
};

// For a standard name ("Helvetica-Bold", "Symbol"); nothing for any other.
std::optional<Std14Widths> std14_widths(std::string_view name);

}
